const anchor=(s:string)=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
export const GLOSSARY:readonly GlossaryEntry[]=[
 ...PLAIN.map(([term,def,to,toName])=>({term,id:anchor(term),def,to,toName})),
 ...TERM_PAGES.map(t=>({term:t.name,id:t.slug,def:t.short,to:t.path,toName:`${t.name}: diagram and how to do it`})),
].sort((a,b)=>a.term.localeCompare(b.term,'en',{numeric:false}));
if(new Set(GLOSSARY.map(g=>g.id)).size!==GLOSSARY.length)throw new Error('glossary: two terms share an anchor');
/** A-Z sections; a term that starts with a digit (2v1) is filed under its first letter word ("T" for two). */
const letterOf=(g:GlossaryEntry)=>/^\d/.test(g.term)?'T':g.term[0].toUpperCase();
export const GLOSSARY_LETTERS=[...new Set(GLOSSARY.map(letterOf))].sort().map(letter=>({letter,terms:GLOSSARY.filter(g=>letterOf(g)===letter)}));
